for _p in PAGES:
    _p.update(EXTRA[_p["slug"]])
BY_SLUG = {p["slug"]: p for p in PAGES}


def og(p):
    return f"{SITE}/assets/og/lab-{p['slug']}.png"


def url(p):
    return f"/medical-ai/lab/{p['slug']}/"


def extract(hub):
    def one(pattern):
        m = re.search(pattern, hub, re.S)
        assert m, pattern
        return m.group(0)
    parts = {
        "fonts": one(r'<link rel="preconnect" href="https://fonts.googleapis.com">.*?rel="stylesheet">'),
        "ga": one(r"<script>\(function\(\)\{var GA=.*?</script>"),
        "quicknav": one(r'<nav class="site-quick-nav".*?</nav>'),
        "note": one(r'<p class="lab-note">.*?</p>'),
        "noscript": one(r"<noscript>.*?</noscript>"),
        "contact": one(r'<section class="c-contact" id="contact".*?</section>'),
        "footer": one(r'<footer class="c-footer">.*?</footer>'),
        "sections": {},
    }
    for p in PAGES:
        sec = one(r'<section class="lab-experiment c-sec" id="%s".*?</section>' % re.escape(p["section"]))
        sec = re.sub(r'<a class="lab-open"[^>]*>.*?</a>', "", sec)  # hub-only "Open as a page" link
        sec = re.sub(r'href="#([a-z-]+)"', lambda m: f'href="{url(BY_SECTION[m.group(1)])}"' if m.group(1) in BY_SECTION else m.group(0), sec)
        parts["sections"][p["section"]] = sec
    return parts


def jsonld(p):
    page_url = SITE + url(p)
    crumbs = {"@context": "https://schema.org", "@type": "BreadcrumbList", "itemListElement": [
        {"@type": "ListItem", "position": 1, "name": "MLAIA", "item": SITE + "/"},
        {"@type": "ListItem", "position": 2, "name": "Medical AI", "item": SITE + "/medical-ai/"},
        {"@type": "ListItem", "position": 3, "name": "Medical AI lab", "item": SITE + "/medical-ai/lab/"},
        {"@type": "ListItem", "position": 4, "name": p["name"], "item": page_url},
    ]}
    resource = {"@context": "https://schema.org", "@type": ["WebPage", "LearningResource"],
                "name": p["name"], "description": p["description"], "url": page_url,
                "inLanguage": "en", "isAccessibleForFree": True,
                "learningResourceType": "Interactive simulation", "teaches": p["teaches"],
                "image": og(p),
                "isPartOf": {"@type": "WebPage", "name": "Interactive Medical AI Lab", "url": SITE + "/medical-ai/lab/"},
                "provider": {"@id": SITE + "/#organization"}}
    faq = {"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [
        {"@type": "Question", "name": q, "acceptedAnswer": {"@type": "Answer", "text": a}} for q, a in p["faq"]]}
    dump = lambda o: json.dumps(o, ensure_ascii=False, separators=(",", ":"))
    return (f'<script type="application/ld+json">{dump(crumbs)}</script>'
            f'<script type="application/ld+json">{dump(resource)}</script>'
            f'<script type="application/ld+json">{dump(faq)}</script>')


def extra_sections(p):
    """Worked example, checklist + related links, and the visible FAQ (plain text, same strings as the JSON-LD)."""
    t = lambda s: html.escape(s, quote=False)
    topic_href, _, topic_label = TOPICS[p["topic"]]
    def split(kicker, hid, heading, body):
        return (f'<section class="c-sec lab-explain" aria-labelledby="{hid}"><div class="c-wrap c-split"><div class="c-split__head">'
                f'<p class="c-kicker">{kicker}</p><h2 class="c-h2" id="{hid}">{heading}</h2></div><div class="c-prose">{body}</div></div></section>')
    worked = "".join(f"<p>{t(x)}</p>" for x in p["worked"])
    siblings = " and ".join(f'<a href="{url(BY_SLUG[s])}">{t(BY_SLUG[s]["link"])}</a>' for s in p["siblings"])
    related = (f'<p>Related: our <a href="{topic_href}">{topic_label}</a> service, the wiki page on '
               f'<a href="/wiki/medical-ai-validation.html">medical AI validation</a>, and the demos on {siblings}.</p>')
    check = "<ul>" + "".join(f"<li>{t(x)}</li>" for x in p["check"]) + "</ul>" + related
    faq = "".join(
        (f'<h3 style="margin-top:0">{t(q)}</h3>' if i == 0 else f"<h3>{t(q)}</h3>") + f"<p>{t(a)}</p>"
        for i, (q, a) in enumerate(p["faq"]))
    return [
        split("Worked example", "worked-title", t(p["worked_h"]), worked),
        split("Checklist", "check-title", "What to check in your own project", check),
        split("FAQ", "faq-title", "Common questions", faq),
    ]


def build(p, parts):
    e = html.escape
    page_url = SITE + url(p)
    OG = og(p)
    topic_href, topic_name, topic_label = TOPICS[p["topic"]]
    topic_link = f'<a href="{topic_href}">{topic_label}</a>'
    body = "".join(f"<p>{para.format(topic=topic_link)}</p>" for para in p["body"])
    jumps = "".join(
        f'<a href="{url(q)}"' + (' aria-current="page"' if q is p else "") + f'>{q["num"]} / {e(q["short"])}</a>'
        for q in PAGES)
    tiles = "".join(
        f'<a class="c-tile" href="{url(q)}"><small>{q["num"]} / {e(q["short"])}</small><strong>{q["name"]}</strong><span>{q["tile"]}</span></a>'
        for q in PAGES if q is not p)
    scripts = "".join(f'<script src="/assets/{s}" defer></script>' for s in p.get("scripts", []))
    head = (
        '<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
        f'<title>{e(p["title"], quote=False)}</title><meta name="description" content="{e(p["description"])}">'
        + parts["fonts"] + "\n"
        '<link rel="stylesheet" href="/assets/mlaia-c.css"><link rel="stylesheet" href="/assets/audio-lab.css"><link rel="stylesheet" href="/assets/medical-lab.css">'
        + scripts + '<script src="/assets/medical-lab.js" defer></script>'
        f'<link rel="canonical" href="{page_url}">'
        f'<meta property="og:title" content="{e(p["title"])}"><meta property="og:description" content="{e(p["description"])}">'
        f'<meta property="og:type" content="website"><meta property="og:url" content="{page_url}">'
        f'<meta property="og:image" content="{OG}"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630">'
        f'<meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{e(p["title"])}">'
        f'<meta name="twitter:description" content="{e(p["description"])}"><meta name="twitter:image" content="{OG}">'
        + jsonld(p)
        + '<link rel="stylesheet" href="/assets/site-shell.css"><script src="/assets/site-shell.js" defer></script>'
        + parts["ga"] + "</head>"
    )
    return "\n".join([
        head + '<body class="practice-page audio-lab medical-lab lab-demo-page c-page" data-site-shell="true">',
        GENERATED,
        parts["quicknav"],
        f'<a class="c-skip" href="#main">Skip to the {e(p["short"].lower())} demo</a>',
        '<header class="c-nav">\n  <div class="c-wrap c-nav__inner">\n    <a class="c-logo" href="/">MLAIA</a>\n'
        '    <nav class="lab-nav" aria-label="Main navigation">\n      <a href="/medical-ai/lab/">← Medical AI lab</a>\n'
        '      <a class="c-btn" href="#contact">Let’s talk</a>\n    </nav>\n  </div>\n</header>',
        '<main class="lab-main" id="main">',
        '<section class="c-hero lab-hero" aria-labelledby="page-title">',
        '<div class="c-wrap"><div class="lab-heading lab-heading--demo"><div>'
        f'<nav class="c-crumb" aria-label="Breadcrumb"><a href="/">MLAIA</a> / <a href="/medical-ai/">Medical AI</a> / <a href="/medical-ai/lab/">Medical AI lab</a> / {e(p["short"])}</nav>'
        f'<p class="c-kicker"><span class="c-idx" aria-hidden="true">{p["num"]}</span>{e(p["kicker"])}</p>'
        f'<h1 class="c-display" id="page-title">{p["h1"]}</h1>'
        f'<p class="lab-answer">{p["answer"]}</p></div><span class="lab-badge">SYNTHETIC DATA</span></div></div>',
        f'<div class="lab-toolbar"><div class="c-wrap lab-toolbar__inner"><nav class="lab-jumps" aria-label="Medical AI lab demos">{jumps}</nav></div></div>',
        f'<div class="c-wrap">{parts["note"]}{parts["noscript"]}<p class="lab-status">Nothing is uploaded. No patient data is used.</p></div>',
        "</section>",
        parts["sections"][p["section"]],
        f'<section class="c-sec lab-explain" aria-labelledby="explain-title"><div class="c-wrap c-split"><div class="c-split__head"><p class="c-kicker">The principle</p><h2 class="c-h2" id="explain-title">How it works</h2></div>'
        f'<div class="c-prose">{body}</div></div></section>',
        *extra_sections(p),
        f'<section class="c-sec lab-more" aria-labelledby="more-title"><div class="c-wrap"><p class="c-kicker">Medical AI lab</p><h2 class="c-h2" id="more-title">More demos</h2>'
        f'<div class="c-tiles">{tiles}</div>'
        f'<p class="c-links"><a class="c-link" href="/medical-ai/lab/">All six demos on one page: the medical AI lab</a><a class="c-link" href="{topic_href}">{topic_name} →</a></p></div></section>',
        '<section class="c-sec lab-end-sec" aria-label="Next steps"><div class="c-wrap lab-end"><a class="c-btn" href="/medical-ai/#contact">Discuss your clinical AI project →</a><a class="c-link" href="/#interactive-demos">Explore all demonstrations</a></div></section>',
        "</main>",
        parts["contact"],
        parts["footer"],
        "</body></html>",
        "",
    ])


def main():
    parts = extract(HUB.read_text(encoding="utf-8"))
    for p in PAGES:
        out = ROOT / "medical-ai" / "lab" / p["slug"] / "index.html"
        out.parent.mkdir(parents=True, exist_ok=True)
        out.write_text(build(p, parts), encoding="utf-8")
        words = len(re.sub(r"<[^>]+>", " ", " ".join(p["body"])).split())
        worked = len(" ".join(p["worked"]).split())
        print(f"{out.relative_to(ROOT)}  explainer {words} words, worked example {worked} words, {len(p['faq'])} FAQ")


if __name__ == "__main__":
    main()
